    if(ir){
      var iw=Number(base.imageW)||0,ih=Number(base.imageH)||0,rm=String(base.revealMode||"none");
      if(rm==="radial"){
        ir.setAttribute("r",String(Math.hypot(iw,ih)*0.5*rp));
      }else{
        var horizontal=rm==="left"||rm==="right";
        var rw=horizontal?iw*rp:iw,rh=horizontal?ih:ih*rp;
        ir.setAttribute("width",String(rw));
        ir.setAttribute("height",String(rh));
        ir.setAttribute("x",String(rm==="right"?iw-rw:0));
        ir.setAttribute("y",String(rm==="down"?ih-rh:0));
      }
    }
  }
  var sh=$(P+"-sh-"+id);
  if(sh){
    if(props.fill!==undefined&&base.fill)sh.setAttribute("fill",s(props,base,"fill"));
    if(props.stroke!==undefined&&base.stroke)sh.setAttribute("stroke",s(props,base,"stroke"));
    if(props.strokeWidth!==undefined)sh.setAttribute("stroke-width",String(n(props,base,"strokeWidth")));
    if(geom.stops){
      for(var si=0;si<geom.stops.length;si++){
        var stopEl=$(P+"-f-"+id+"-s"+si);
        if(!stopEl)continue;
        var sc=props["stopColor:"+si],so=props["stopOffset:"+si];
        if(sc!==undefined)stopEl.setAttribute("stop-color",String(sc));
        if(so!==undefined)stopEl.setAttribute("offset",String(so));
      }
    }
  }
  var trimEnd=props.trim!==undefined?Number(props.trim):1;
  var trimStart=props.trimStart!==undefined?Number(props.trimStart):0;
  var widthScale=props.widthScale!==undefined?Number(props.widthScale):1;
  if(geom.chunks&&(props.trim!==undefined||props.trimStart!==undefined||props.widthScale!==undefined)){
    for(var ci=0;ci<geom.chunks.length;ci++){
      var c=geom.chunks[ci],mc=$(P+"-mc-"+id+"-"+ci);
      if(!mc)continue;
      var span=c.endFrac-c.startFrac;
      var ls=span<=0?0:Math.max(0,Math.min(1,(trimStart-c.startFrac)/span));
      var le=span<=0?1:Math.max(0,Math.min(1,(trimEnd-c.startFrac)/span));
      var visLen=Math.max(0,(le-ls)*c.length);
      mc.setAttribute("stroke-dasharray",visLen.toFixed(2)+" "+(c.length+10).toFixed(2));
      mc.setAttribute("stroke-dashoffset",String(-(ls*c.length).toFixed(2)));
      mc.setAttribute("stroke-width",String((c.width*widthScale).toFixed(2)));
